import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose3d_forward(
    torch::Tensor x, torch::Tensor weight, torch::Tensor bias_opt,
    int64_t stride, int64_t padding, int64_t output_padding);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <algorithm>

using namespace cute;

__global__ void conv_transpose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int Cin, int D, int H, int W,
    int Cout, int K,
    int Dout, int Hout, int Wout,
    int stride, int padding,
    int TILE_OW, int numOWTiles)
{
    extern __shared__ float smem[];
    float* s_w  = smem;                    // Cin*Cout
    float* s_in = smem + Cin * Cout;       // TILE_OW*Cin

    // Build CUTE tensors over global memory with runtime strides (row-major contiguous)
    int64_t sN_in = (int64_t)Cin * D * H * W;
    int64_t sC_in = (int64_t)D * H * W;
    int64_t sD_in = (int64_t)H * W;
    int64_t sH_in = (int64_t)W;

    int64_t sCi_w = (int64_t)Cout * K * K * K;
    int64_t sCo_w = (int64_t)K * K * K;
    int64_t sKd_w = (int64_t)K * K;
    int64_t sKh_w = (int64_t)K;

    int64_t sN_out = (int64_t)Cout * Dout * Hout * Wout;
    int64_t sC_out = (int64_t)Dout * Hout * Wout;
    int64_t sD_out = (int64_t)Hout * Wout;
    int64_t sH_out = (int64_t)Wout;

    Tensor gIn = make_tensor(make_gmem_ptr(input),
        make_shape(N, Cin, D, H, W),
        make_stride(sN_in, sC_in, sD_in, sH_in, (int64_t)1));

    Tensor gW = make_tensor(make_gmem_ptr(weight),
        make_shape(Cin, Cout, K, K, K),
        make_stride(sCi_w, sCo_w, sKd_w, sKh_w, (int64_t)1));

    Tensor gOut = make_tensor(make_gmem_ptr(output),
        make_shape(N, Cout, Dout, Hout, Wout),
        make_stride(sN_out, sC_out, sD_out, sH_out, (int64_t)1));

    int n = blockIdx.x;
    int od = blockIdx.y;
    int combined = blockIdx.z;
    int oh = combined / numOWTiles;
    int ow_tile = combined % numOWTiles;

    int oc = threadIdx.x;
    int ow_local = threadIdx.y;
    int ow = ow_tile * TILE_OW + ow_local;

    int tid = threadIdx.y * blockDim.x + threadIdx.x;
    int nthreads = blockDim.x * blockDim.y;

    float acc = 0.0f;
    bool valid_ow = (ow < Wout);

    for (int kd = 0; kd < K; ++kd) {
        int id_num = od + padding - kd;
        if (id_num % stride != 0) continue;
        int id = id_num / stride;
        if (id < 0 || id >= D) continue;

        for (int kh = 0; kh < K; ++kh) {
            int ih_num = oh + padding - kh;
            if (ih_num % stride != 0) continue;
            int ih = ih_num / stride;
            if (ih < 0 || ih >= H) continue;

            for (int kw = 0; kw < K; ++kw) {
                // Cooperative load of weight slice [Cin, Cout] for this (kd,kh,kw)
                int total_w = Cin * Cout;
                for (int idx = tid; idx < total_w; idx += nthreads) {
                    int ci = idx / Cout;
                    int co = idx % Cout;
                    s_w[idx] = gW(ci, co, kd, kh, kw);
                }

                // Cooperative load of input tile [TILE_OW, Cin] for this (id,ih,kw)
                int total_in = TILE_OW * Cin;
                for (int idx = tid; idx < total_in; idx += nthreads) {
                    int owl = idx / Cin;
                    int ci  = idx % Cin;
                    int ow_g = ow_tile * TILE_OW + owl;
                    float val = 0.0f;
                    if (ow_g < Wout) {
                        int iw_num = ow_g + padding - kw;
                        if (iw_num % stride == 0) {
                            int iw = iw_num / stride;
                            if (iw >= 0 && iw < W) {
                                val = gIn(n, ci, id, ih, iw);
                            }
                        }
                    }
                    s_in[idx] = val;
                }

                __syncthreads();

                if (valid_ow) {
                    #pragma unroll 4
                    for (int ci = 0; ci < Cin; ++ci) {
                        acc += s_in[ow_local * Cin + ci] * s_w[ci * Cout + oc];
                    }
                }
                __syncthreads();
            }
        }
    }

    if (valid_ow) {
        if (bias != nullptr) acc += bias[oc];
        gOut(n, oc, od, oh, ow) = acc;
    }
}

torch::Tensor conv_transpose3d_forward(
    torch::Tensor x, torch::Tensor weight, torch::Tensor bias_opt,
    int64_t stride, int64_t padding, int64_t output_padding)
{
    TORCH_CHECK(x.is_cuda() && weight.is_cuda(), "x and weight must be CUDA tensors");
    TORCH_CHECK(x.scalar_type() == at::kFloat && weight.scalar_type() == at::kFloat,
                "Only float32 supported");
    TORCH_CHECK(x.dim() == 5, "x must be 5D (N,C,D,H,W)");
    TORCH_CHECK(weight.dim() == 5, "weight must be 5D (Cin,Cout,K,K,K)");

    auto xc = x.contiguous();
    auto wc = weight.contiguous();

    bool has_bias = bias_opt.defined() && bias_opt.numel() > 0;
    torch::Tensor bc;
    if (has_bias) {
        bc = bias_opt.contiguous();
    }

    int N   = (int)xc.size(0);
    int Cin = (int)xc.size(1);
    int D   = (int)xc.size(2);
    int H   = (int)xc.size(3);
    int W   = (int)xc.size(4);

    int Cout = (int)wc.size(1);
    int K    = (int)wc.size(2);

    int s  = (int)stride;
    int p  = (int)padding;
    int op = (int)output_padding;

    int Dout = (D - 1) * s - 2 * p + K + op;
    int Hout = (H - 1) * s - 2 * p + K + op;
    int Wout = (W - 1) * s - 2 * p + K + op;

    auto output = torch::zeros({N, Cout, Dout, Hout, Wout}, xc.options());

    int TILE_OW = std::max(1, std::min(16, 1024 / Cout));
    int numOWTiles = (Wout + TILE_OW - 1) / TILE_OW;

    dim3 block(Cout, TILE_OW);
    dim3 grid(N, Dout, Hout * numOWTiles);

    size_t smem_bytes = (size_t)(Cin * Cout + TILE_OW * Cin) * sizeof(float);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    conv_transpose3d_kernel<<<grid, block, smem_bytes, stream>>>(
        xc.data_ptr<float>(),
        wc.data_ptr<float>(),
        has_bias ? bc.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        N, Cin, D, H, W,
        Cout, K,
        Dout, Hout, Wout,
        s, p,
        TILE_OW, numOWTiles);

    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "conv_transpose3d kernel launch failed");
    return output;
}
"""

cute_ext = load_inline(
    name="cute_conv_transpose3d_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["conv_transpose3d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Performs a transposed 3D convolution with square input and square kernel,
    using a custom CUTE-based CUDA kernel for the forward computation.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, output_padding: int = 0,
                 groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        # Keep an nn.ConvTranspose3d purely as a parameter container so that
        # initialization matches the reference implementation exactly.
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels, out_channels,
            kernel_size=(kernel_size, kernel_size, kernel_size),
            stride=stride, padding=padding, output_padding=output_padding,
            groups=groups, bias=bias,
        )
        assert groups == 1, "Custom kernel currently supports groups=1 only"
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        weight = self.conv_transpose3d.weight
        bias = self.conv_transpose3d.bias
        if bias is None:
            bias_t = torch.empty(0, dtype=x.dtype, device=x.device)
        else:
            bias_t = bias

        x_in = x.cuda() if not x.is_cuda else x
        weight = weight.to(x_in.device)
        bias_t = bias_t.to(x_in.device)

        return self._ext.conv_transpose3d_forward(
            x_in, weight, bias_t,
            int(self.stride), int(self.padding), int(self.output_padding)
        )

