                        acc += s_in[ow_local * Cin + ci] * s_w[ci * Cout + oc];
                    }
                }
                __syncthreads();
            }
        }
    }

    if (valid_ow) {
        if (bias != nullptr) acc += bias[oc];
        gOut(n, oc, od, oh, ow) = acc;
    }
}

torch::Tensor conv_transpose3d_forward(
    torch::Tensor x, torch::Tensor weight, torch::Tensor bias_opt,
    int64_t stride, int64_t padding, int64_t output_padding)
{
    TORCH_CHECK(x.is_cuda() && weight.is_cuda(), "x and weight must be CUDA tensors");
    TORCH_CHECK(x.scalar_type() == at::kFloat && weight.scalar_type() == at::kFloat,
                "Only float32 supported");
    TORCH_CHECK(x.dim() == 5, "x must be 5D (N,C,D,H,W)");
    TORCH_CHECK(weight.dim() == 5, "weight must be 5D (Cin,Cout,K,K,K)");

    auto xc = x.contiguous();
    auto wc = weight.contiguous();

    bool has_bias = bias_opt.defined() && bias_opt.numel() > 0;
    torch::Tensor bc;
    if (has_bias) {
        bc = bias_opt.contiguous();
    }

    int N   = (int)xc.size(0);
    int Cin = (int)xc.size(1);
    int D   = (int)xc.size(2);
    int H   = (int)xc.size(3);
    int W   = (int)xc.size(4);

    int Cout = (int)wc.size(1);
    int K    = (int)wc.size(2);

    int s  = (int)stride;
    int p  = (int)padding;
    int op = (int)output_padding;

    int Dout = (D - 1) * s - 2 * p + K + op;
    int Hout = (H - 1) * s - 2 * p + K + op;
    int Wout = (W - 1) * s - 2 * p + K + op;

    auto output = torch::zeros({N, Cout, Dout, Hout, Wout}, xc.options());

    int TILE_OW = std::max(1, std::min(16, 1024 / Cout));
    int numOWTiles = (Wout + TILE_OW - 1) / TILE_OW;

    dim3 block(Cout, TILE_OW);
    dim3 grid(N, Dout, Hout * numOWTiles);

    size_t smem_bytes = (size_t)(Cin * Cout + TILE_OW * Cin) * sizeof(float);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    conv_transpose3d_kernel<<<grid, block, smem_bytes, stream>>>(
        xc.data_ptr<float>(),
        wc.data_ptr<float>(),
        has_bias ? bc.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        N, Cin, D, H, W,
        Cout, K,
        Dout, Hout, Wout,
        s, p,
        TILE_OW, numOWTiles);

    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "conv_transpose3d kernel launch failed");
    return output;
}
