class ModelNew(nn.Module):
    """
    Performs a transposed 3D convolution with square input and square kernel,
    using a custom CUTE-based CUDA kernel for the forward computation.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, output_padding: int = 0,
                 groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        # Keep an nn.ConvTranspose3d purely as a parameter container so that
        # initialization matches the reference implementation exactly.
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels, out_channels,
            kernel_size=(kernel_size, kernel_size, kernel_size),
            stride=stride, padding=padding, output_padding=output_padding,
            groups=groups, bias=bias,
        )
        assert groups == 1, "Custom kernel currently supports groups=1 only"
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self._ext = cute_ext

